//! Opcode parity audit: Chorizite.ACProtocol → holtburger-protocol.
//!
//! This test loads `external/holtburger/apps/holtburger-web/data/chorizite/
//! chorizite-acprotocol-opcodes.json` (generated by the WB.Terminal
//! `chorizite-dump-opcodes` command) and asserts that the three Rust opcode
//! enums in `crate::opcodes` agree with the upstream Chorizite.ACProtocol
//! enums on (value → name) for every variant.
//!
//! Mapping (ACProtocol → Rust):
//!   - `C2SMessageType` ∪ `S2CMessageType`     →  `GameOpcode`
//!   - `GameActionType`                        →  `GameActionOpcode`
//!   - `GameEventType`                         →  `GameEventOpcode`
//!
//! Names are NOT expected to match between the two sources — Chorizite uses
//! `Category_VerbNoun` (e.g. `Combat_TargetedMeleeAttack`) while
//! holtburger-protocol uses bare PascalCase (e.g. `TargetedMeleeAttack`). The
//! test asserts on numeric values only and reports name pairs purely for
//! human diff readability.
//!
//! Initial state: this test is gated as `#[ignore]` because it is an audit
//! — drift IS expected and is documented in the test output. Run with
//! `cargo test -p holtburger-protocol -- --ignored opcode_parity` to surface
//! the report. See the TASK 2E report (rev 2026-05-19) for the scope estimate.
//!
//! The test deliberately does NOT depend on `serde_json`. The JSON shape is
//! tightly constrained (no nesting beyond two levels, no escapes in keys or
//! string values), so a hand-rolled tokenizer is sufficient and avoids
//! mutating the crate's Cargo.toml dev-dependencies.

use std::collections::BTreeMap;
use std::path::PathBuf;

use holtburger_protocol::opcodes::{GameActionOpcode, GameEventOpcode, GameOpcode};

/// Path to the generated JSON, relative to the crate manifest.
const JSON_REL_PATH: &str = "../../apps/holtburger-web/data/chorizite/chorizite-acprotocol-opcodes.json";

/// One enum slice of the dump: { hex_string → ACProtocol_name }.
type OpcodeMap = BTreeMap<u32, String>;

fn load_json() -> BTreeMap<String, OpcodeMap> {
    let mut path = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    path.push(JSON_REL_PATH);
    let src = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "Failed to read {} ({}). Regenerate via:\n  cd WorldBuilder.Terminal && \\\n    echo '{{\"command\":\"chorizite-dump-opcodes\"}}' | dotnet run --no-build -- --stdin\n",
            path.display(),
            e
        )
    });
    parse_opcode_json(&src)
}

/// Minimal hand-rolled parser tailored to the canonical shape emitted by the
/// `chorizite-dump-opcodes` command. It walks the file looking for nested
/// `"EnumName": { "0xHEX": "VariantName", ... }` blocks under the top-level
/// `"enums"` key. Anything outside that — `generatedBy`, `vendoredHead`,
/// `source` — is ignored. The output preserves the discovered order via the
/// internal BTreeMap ordering on the numeric opcode key.
fn parse_opcode_json(src: &str) -> BTreeMap<String, OpcodeMap> {
    // Locate the "enums": { … } block. We scan for the literal `"enums"`
    // key, then walk forward to the matching closing brace, counting depth.
    let enums_idx = src
        .find("\"enums\"")
        .expect("JSON missing top-level \"enums\" key — re-generate the dump");
    let after = &src[enums_idx..];
    let open_idx = enums_idx
        + after
            .find('{')
            .expect("JSON missing { after \"enums\"");
    let mut depth = 0i32;
    let mut end_idx = open_idx;
    for (i, ch) in src[open_idx..].char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    end_idx = open_idx + i + 1;
                    break;
                }
            }
            _ => {}
        }
    }
    assert!(depth == 0, "JSON \"enums\" block did not close cleanly");
    let body = &src[open_idx + 1..end_idx - 1]; // strip outer braces

    // Walk inner blocks: each is `"EnumName": { ... },` with the inner block
    // containing `"0xHEX": "Name",` entries.
    let mut out = BTreeMap::new();
    let mut cursor = 0usize;
    while let Some(name_start_rel) = body[cursor..].find('"') {
        let name_start = cursor + name_start_rel + 1;
        let name_end = name_start
            + body[name_start..]
                .find('"')
                .expect("malformed enum name in JSON");
        let enum_name = body[name_start..name_end].to_string();

        // Move past `":` and find the opening `{`.
        let block_open = name_end
            + body[name_end..]
                .find('{')
                .expect("malformed enum body in JSON");
        let mut block_depth = 0i32;
        let mut block_end = block_open;
        for (i, ch) in body[block_open..].char_indices() {
            match ch {
                '{' => block_depth += 1,
                '}' => {
                    block_depth -= 1;
                    if block_depth == 0 {
                        block_end = block_open + i + 1;
                        break;
                    }
                }
                _ => {}
            }
        }
        let inner = &body[block_open + 1..block_end - 1];

        // Parse each `"0xHEX": "Name"` pair.
        let mut members = OpcodeMap::new();
        let mut p = 0usize;
        while let Some(k_open_rel) = inner[p..].find('"') {
            let k_open = p + k_open_rel + 1;
            let k_close = k_open + inner[k_open..].find('"').expect("malformed key");
            let key = &inner[k_open..k_close];
            // Advance past `":`
            let after_colon = k_close
                + inner[k_close..]
                    .find(':')
                    .expect("malformed pair (no colon)")
                + 1;
            let v_open_rel = inner[after_colon..]
                .find('"')
                .expect("malformed pair (no value open quote)");
            let v_open = after_colon + v_open_rel + 1;
            let v_close = v_open + inner[v_open..].find('"').expect("malformed value");
            let value = &inner[v_open..v_close];

            assert!(
                key.starts_with("0x") || key.starts_with("0X"),
                "expected hex string key, got {key:?}"
            );
            let opcode = u32::from_str_radix(&key[2..], 16)
                .unwrap_or_else(|e| panic!("could not parse hex key {key:?}: {e}"));
            members.insert(opcode, value.to_string());

            p = v_close + 1;
        }

        out.insert(enum_name, members);
        cursor = block_end;
    }

    out
}

/// Enumerate every variant of a Rust opcode enum, returning a
/// `BTreeMap<u32, String>` of (value → Debug-formatted variant name).
///
/// `strum_macros::FromRepr` generates an inherent `from_repr` method on the
/// enum but NOT a generic `FromRepr` trait. Rather than introduce a custom
/// trait (which would force the production `opcodes.rs` to implement it) we
/// brute-force scan the relevant u32 range — fast enough since the upper
/// bound is < 0x10000 for these protocol opcodes.
///
/// Why a macro instead of a `fn<T>`: `from_repr` lives in inherent impl
/// space, so we can't write `T::from_repr(v)` generically without binding to
/// a trait. The macro expands the per-type scan at call site.
macro_rules! enumerate_rust {
    ($enum_ty:ty) => {{
        let mut out: BTreeMap<u32, String> = BTreeMap::new();
        // 0xEA60 (AdminEnvirons-class range) through 0xF7FF cover every
        // currently-defined opcode across all three Rust enums with margin.
        for v in 0u32..0xF800u32 {
            if let Some(variant) = <$enum_ty>::from_repr(v) {
                out.insert(v, format!("{variant:?}"));
            }
        }
        out
    }};
}

/// Collect every diff line and print them ALL at the end. Don't short-circuit
/// on first failure — the audit's value is the full report.
struct DiffReport {
    enum_label: &'static str,
    missing_in_rust: Vec<(u32, String)>,
    missing_in_chor: Vec<(u32, String)>,
}

impl DiffReport {
    fn render(&self) -> String {
        let mut s = String::new();
        if !self.missing_in_rust.is_empty() {
            s.push_str(&format!(
                "  [{}] {} opcodes in Chorizite.ACProtocol but NOT in Rust:\n",
                self.enum_label,
                self.missing_in_rust.len()
            ));
            for (v, name) in &self.missing_in_rust {
                s.push_str(&format!("    0x{v:04X} {name}\n"));
            }
        }
        if !self.missing_in_chor.is_empty() {
            s.push_str(&format!(
                "  [{}] {} opcodes in Rust but NOT in Chorizite.ACProtocol:\n",
                self.enum_label,
                self.missing_in_chor.len()
            ));
            for (v, name) in &self.missing_in_chor {
                s.push_str(&format!("    0x{v:04X} {name}\n"));
            }
        }
        s
    }

    fn is_empty(&self) -> bool {
        self.missing_in_rust.is_empty() && self.missing_in_chor.is_empty()
    }
}

fn diff(
    label: &'static str,
    chor: &OpcodeMap,
    rust: &BTreeMap<u32, String>,
) -> DiffReport {
    let mut missing_in_rust = Vec::new();
    let mut missing_in_chor = Vec::new();

    for (v, name) in chor {
        if !rust.contains_key(v) {
            missing_in_rust.push((*v, name.clone()));
        }
    }
    for (v, name) in rust {
        if !chor.contains_key(v) {
            missing_in_chor.push((*v, name.clone()));
        }
    }

    DiffReport {
        enum_label: label,
        missing_in_rust,
        missing_in_chor,
    }
}

/// TASK 2E parity audit. Initially expected to FAIL — the holtburger-protocol
/// opcode enums are curated for the slice of the protocol that has live
/// implementation in the WASM client, while Chorizite.ACProtocol covers the
/// full retail protocol. The test surfaces the gap as a structured diff for
/// future Phase-by-phase port work.
///
/// To run: `cargo test -p holtburger-protocol -- --ignored opcode_parity`
#[test]
#[ignore = "TASK 2E: audit-only — drift IS expected; un-ignore once all three opcodes line up"]
fn opcode_parity_chorizite_vs_holtburger() {
    let chor = load_json();

    // Union C2SMessageType and S2CMessageType for GameOpcode parity. We use
    // a fresh BTreeMap rather than touching the originals.
    let mut chor_game = OpcodeMap::new();
    for (v, name) in chor.get("C2SMessageType").expect("C2SMessageType missing") {
        chor_game.insert(*v, format!("C2S:{name}"));
    }
    for (v, name) in chor.get("S2CMessageType").expect("S2CMessageType missing") {
        // Overwrite if both directions claim the same opcode — these are
        // bidirectional. e.g. TurbineChat 0xF7DE is sent both ways.
        chor_game
            .entry(*v)
            .and_modify(|existing| {
                *existing = format!("{existing}+S2C:{name}");
            })
            .or_insert_with(|| format!("S2C:{name}"));
    }

    let chor_action = chor.get("GameActionType").expect("GameActionType missing");
    let chor_event = chor.get("GameEventType").expect("GameEventType missing");

    let rust_game = enumerate_rust!(GameOpcode);
    let rust_action = enumerate_rust!(GameActionOpcode);
    let rust_event = enumerate_rust!(GameEventOpcode);

    let report_game = diff("GameOpcode", &chor_game, &rust_game);
    let report_action = diff("GameActionOpcode", &chor_action, &rust_action);
    let report_event = diff("GameEventOpcode", &chor_event, &rust_event);

    let total_diffs = report_game.missing_in_rust.len()
        + report_game.missing_in_chor.len()
        + report_action.missing_in_rust.len()
        + report_action.missing_in_chor.len()
        + report_event.missing_in_rust.len()
        + report_event.missing_in_chor.len();

    if report_game.is_empty() && report_action.is_empty() && report_event.is_empty() {
        eprintln!("opcode parity PASS — no drift between Chorizite.ACProtocol and holtburger-protocol");
        return;
    }

    let mut msg = String::new();
    msg.push_str(&format!(
        "\nOpcode parity DRIFT — {} total differences:\n",
        total_diffs
    ));
    msg.push_str(&report_game.render());
    msg.push_str(&report_action.render());
    msg.push_str(&report_event.render());
    msg.push_str("\nNOTE: holtburger-protocol intentionally curates a subset; gaps are\n");
    msg.push_str("not necessarily bugs. Un-comment-out opcodes in src/opcodes.rs as the\n");
    msg.push_str("corresponding messages are wired up, and remove this #[ignore] when\n");
    msg.push_str("full parity is desired.\n");

    panic!("{}", msg);
}

/// Sanity-only test (NOT ignored) that asserts the JSON file is present and
/// parses cleanly. This catches "WB.Terminal regenerated the dump but
/// emitted malformed JSON" failure modes without requiring the full diff
/// audit to be un-ignored.
#[test]
fn opcode_parity_dump_is_well_formed() {
    let parsed = load_json();
    // The five expected enums.
    for name in &[
        "C2SMessageType",
        "S2CMessageType",
        "GameActionType",
        "GameEventType",
        "GameMessageGroup",
    ] {
        let block = parsed
            .get(*name)
            .unwrap_or_else(|| panic!("expected enum {name} missing from dump"));
        assert!(
            !block.is_empty(),
            "dumped enum {name} has zero members"
        );
    }
    // Spot-check a stable, well-known opcode.
    let actions = parsed.get("GameActionType").unwrap();
    let melee = actions
        .get(&0x0008)
        .expect("GameActionType is missing 0x0008 (TargetedMeleeAttack)");
    assert!(
        melee.contains("TargetedMeleeAttack"),
        "GameActionType 0x0008 should be TargetedMeleeAttack, got {melee:?}"
    );
}
